// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.csf;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.Arrays;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.junit.jupiter.api.Test;

class PageTextPrototypePagesTest {

	@Test
	void actualNativePagesMatchHeapOracleAndRoundTripEveryGrouping() {
		for (int entriesPerPage : new int[] { 1, 4, 16, 64, 256, 1024, 4096 }) {
			int entriesPerRow = entriesPerPage == 4096 ? 4 : 1;
			long[] ids = ids(entriesPerPage * 2 + 3, entriesPerRow);
			try (PageTextPrototypePages pages = PageTextPrototypePages.build(ids, entriesPerPage, entriesPerRow)) {
				PageTextPrototypePages.Decoder decoder = pages.newDecoder();
				long[] decoded = new long[entriesPerPage];
				long actualUsed = 0;
				long actualCapacity = 0;
				for (int page = 0; page < pages.pageCount(); page++) {
					PageTextPrototypePages.Page metadata = pages.page(page);
					assertThat(decoder.decodePage(page, decoded)).isEqualTo(metadata.entryCount());
					assertThat(Arrays.copyOf(decoded, metadata.entryCount())).containsExactly(
							Arrays.copyOfRange(ids, metadata.fromEntry(),
									metadata.fromEntry() + metadata.entryCount()));
					CompactCsfPageEncoder.PageImage oracle = oracle(ids, metadata, entriesPerRow, page);
					assertThat(oracle).isNotNull();
					assertThat(pages.copyEncodedPage(page)).containsExactly(oracle.bytes());
					assertThat(metadata.encodedBytes()).isEqualTo(oracle.usedBytes());
					assertThat(metadata.capacityBytes()).isEqualTo(oracle.capacity());
					assertThat(metadata.rowCount()).isEqualTo(oracle.rowCount());
					actualUsed += oracle.usedBytes();
					actualCapacity += oracle.capacity();
				}
				assertThat(pages.usedBytes()).isEqualTo(actualUsed);
				assertThat(pages.capacityBytes()).isEqualTo(actualCapacity);
				assertThat(pages.nativeAllocatedBytes()).isEqualTo(actualCapacity + PackedLongVector.READ_TAIL_PADDING);
				assertThat(decoder.decodedPages()).isEqualTo(pages.pageCount());
				assertThat(decoder.pageBindings()).isEqualTo(pages.pageCount());
			}
		}
	}

	@Test
	void rejectedPagesAreNotBoundOrDecoded() {
		try (PageTextPrototypePages pages = PageTextPrototypePages.build(ids(64, 1), 16)) {
			PageTextPrototypePages.Decoder decoder = pages.newDecoder();
			long[] target = new long[16];
			boolean[] mayMatch = { false, true, false, true };
			for (int page = 0; page < pages.pageCount(); page++) {
				if (mayMatch[page]) {
					decoder.decodePage(page, target);
				}
			}
			assertThat(decoder.decodedPages()).isEqualTo(2);
			assertThat(decoder.pageBindings()).isEqualTo(2);
			decoder.decodePage(3, target);
			assertThat(decoder.decodedPages()).isEqualTo(3);
			assertThat(decoder.pageBindings()).isEqualTo(2);
		}
	}

	@Test
	void additionalSpaceUsesActualImageAndBothAcceleratorPolicies() {
		try (PageTextPrototypePages pages = PageTextPrototypePages.build(ids(1024, 1), 1024)) {
			PageTextPrototypePages.Page page = pages.page(0);
			assertThat(page.acceleratorBytes()).isPositive();
			assertThat(pages.capacityWithExtraBytes(0, 0)).isEqualTo(page.capacityBytes());
			for (int extra : new int[] { 2, 3, 4, 16, 32, 128, 512 }) {
				int retained = (page.encodedBytes() + extra + 255) / 256 * 256;
				int replaced = (page.encodedBytes() - page.acceleratorBytes() + extra + 255) / 256 * 256;
				assertThat(pages.capacityWithExtraBytes(0, extra)).isEqualTo(retained);
				assertThat(pages.capacityWithSummaryReplacingAccelerators(0, extra)).isEqualTo(replaced);
			}
			assertThat(pages.capacityWithExtraBytes(0, 65536)).isEqualTo(-1);
			assertThatThrownBy(() -> pages.capacityWithExtraBytes(0, -1))
					.isInstanceOf(IllegalArgumentException.class);
		}
	}

	@Test
	void ownershipAndGroupingChecksPreventUnsafeOrMisleadingScans() {
		PageTextPrototypePages pages = PageTextPrototypePages.build(ids(4, 1), 4);
		PageTextPrototypePages.Decoder decoder = pages.newDecoder();
		assertThatThrownBy(() -> decoder.decodePage(0, new long[3]))
				.isInstanceOf(IllegalArgumentException.class);
		pages.close();
		pages.close();
		assertThatThrownBy(() -> decoder.decodePage(0, new long[4])).isInstanceOf(IllegalStateException.class);
		assertThatThrownBy(() -> pages.copyEncodedPage(0)).isInstanceOf(IllegalStateException.class);
		assertThatThrownBy(() -> PageTextPrototypePages.build(ids(1025, 1), 1025))
				.isInstanceOf(IllegalArgumentException.class);
		assertThatThrownBy(() -> PageTextPrototypePages.build(ids(4, 1), 4, 3))
				.isInstanceOf(IllegalArgumentException.class);
		assertThatThrownBy(() -> PageTextPrototypePages.build(new long[] { 2, 1 }, 2, 2))
				.isInstanceOf(IllegalArgumentException.class);
		assertThatThrownBy(() -> PageTextPrototypePages.build(new long[] { 1, 1 }, 2, 2))
				.isInstanceOf(IllegalArgumentException.class);
		try (PageTextPrototypePages empty = PageTextPrototypePages.build(new long[0], 4)) {
			assertThat(empty.pageCount()).isZero();
			assertThat(empty.capacityBytes()).isZero();
			assertThat(empty.nativeAllocatedBytes()).isZero();
		}
	}

	private static long[] ids(int count, int entriesPerRow) {
		long[] result = new long[count];
		for (int i = 0; i < count; i++) {
			// Deliberately descending between rows, ascending within each row.
			long ordinal = (long) (count - i / entriesPerRow) * entriesPerRow + i % entriesPerRow;
			result[i] = ValueIds.createId(ValueIds.T_LITERAL, ordinal);
		}
		return result;
	}

	private static CompactCsfPageEncoder.PageImage oracle(long[] ids, PageTextPrototypePages.Page page,
			int entriesPerRow, int pageId) {
		CsfPageData data = new CsfPageData();
		int end = page.fromEntry() + page.entryCount();
		for (int first = page.fromEntry(); first < end; first += entriesPerRow) {
			int count = Math.min(entriesPerRow, end - first);
			long[] row = Arrays.copyOfRange(ids, first, first + count);
			int[] starts = new int[count];
			int[] counts = new int[count];
			Arrays.fill(counts, 1);
			for (int i = 0; i < count; i++) {
				starts[i] = i;
			}
			data.appendRow(ValueIds.createId(ValueIds.T_URI, (long) first / entriesPerRow + 1), row, starts, counts,
					new long[count], count, count);
		}
		return new CompactCsfPageEncoder().tryEncode(data, false, pageId);
	}
}
